/**
 * Dropdown FSM - Finite State Machine for Dropdown visibility and animation
 *
 * This FSM models the visibility lifecycle of a Dropdown component,
 * including animation states for smooth open/close transitions.
 *
 * States:
 * - closed: Dropdown menu is not rendered, not visible
 * - opening: Dropdown menu is rendering, playing enter animation
 * - open: Dropdown menu is fully visible and interactive
 * - closing: Dropdown menu is playing exit animation
 *
 * Events:
 * - OPEN: Request to open the dropdown
 * - CLOSE: Request to close the dropdown (ESC, click outside, item click)
 * - TOGGLE: Toggle the dropdown state
 * - ANIMATION_END: Animation has completed
 *
 * This FSM enables:
 * - Smooth fade animations between states
 * - Proper keyboard navigation during transitions
 * - Preventing close during opening animation (and vice versa)
 * - Consistent visual state for styling via data-visual-state
 */

/**
 * Visibility states for the Dropdown FSM
 */
export type DropdownVisibilityState = 'closed' | 'opening' | 'open' | 'closing';

/**
 * The Dropdown FSM state object
 */
export interface DropdownFSMState {
  /**
   * Current visibility/animation state
   */
  readonly visibility: DropdownVisibilityState;

  /**
   * Whether the dropdown menu should be rendered in DOM
   * True for: opening, open, closing
   * False for: closed
   */
  readonly shouldRender: boolean;

  /**
   * Whether the dropdown should have the 'show' class for CSS animations
   * True for: open
   * False for: opening, closing, closed
   */
  readonly shouldShow: boolean;

  /**
   * Whether keyboard navigation should be active
   * True for: open
   * False for: opening, closing, closed
   */
  readonly keyboardNavActive: boolean;

  /**
   * Whether click outside should close the dropdown
   * True for: open
   * False for: opening, closing, closed
   */
  readonly clickOutsideActive: boolean;
}

/**
 * Events that trigger state transitions in the Dropdown FSM
 */
export type DropdownFSMEvent =
  | { readonly type: 'OPEN' }
  | { readonly type: 'CLOSE' }
  | { readonly type: 'TOGGLE' }
  | { readonly type: 'ANIMATION_END' };

/**
 * Creates the initial FSM state based on the isOpen prop
 *
 * @param isOpen - Whether the dropdown should initially be open
 * @returns The initial FSM state
 */
export function createInitialDropdownFSMState(isOpen: boolean): DropdownFSMState {
  if (isOpen) {
    // If initially open, skip opening animation and go straight to open
    return {
      visibility: 'open',
      shouldRender: true,
      shouldShow: true,
      keyboardNavActive: true,
      clickOutsideActive: true,
    };
  }

  return {
    visibility: 'closed',
    shouldRender: false,
    shouldShow: false,
    keyboardNavActive: false,
    clickOutsideActive: false,
  };
}

/**
 * Pure reducer function for the Dropdown FSM
 *
 * State Transition Table:
 *
 * | Current State | Event          | Next State | shouldRender | shouldShow | keyboardNav | clickOutside |
 * |---------------|----------------|------------|--------------|------------|-------------|--------------|
 * | closed        | OPEN           | opening    | true         | false      | false       | false        |
 * | closed        | CLOSE          | closed     | false        | false      | false       | false        |
 * | closed        | TOGGLE         | opening    | true         | false      | false       | false        |
 * | closed        | ANIMATION_END  | closed     | false        | false      | false       | false        |
 * | opening       | OPEN           | opening    | true         | false      | false       | false        |
 * | opening       | CLOSE          | closing    | true         | false      | false       | false        |
 * | opening       | TOGGLE         | closing    | true         | false      | false       | false        |
 * | opening       | ANIMATION_END  | open       | true         | true       | true        | true         |
 * | open          | OPEN           | open       | true         | true       | true        | true         |
 * | open          | CLOSE          | closing    | true         | false      | false       | false        |
 * | open          | TOGGLE         | closing    | true         | false      | false       | false        |
 * | open          | ANIMATION_END  | open       | true         | true       | true        | true         |
 * | closing       | OPEN           | opening    | true         | false      | false       | false        |
 * | closing       | CLOSE          | closing    | true         | false      | false       | false        |
 * | closing       | TOGGLE         | opening    | true         | false      | false       | false        |
 * | closing       | ANIMATION_END  | closed     | false        | false      | false       | false        |
 *
 * @param state - Current FSM state
 * @param event - Event triggering the transition
 * @returns New FSM state
 */
export function dropdownFSMReducer(
  state: DropdownFSMState,
  event: DropdownFSMEvent
): DropdownFSMState {
  switch (state.visibility) {
    case 'closed':
      switch (event.type) {
        case 'OPEN':
        case 'TOGGLE':
          return {
            visibility: 'opening',
            shouldRender: true,
            shouldShow: false,
            keyboardNavActive: false,
            clickOutsideActive: false,
          };
        case 'CLOSE':
        case 'ANIMATION_END':
          // Already closed, stay closed (idempotent)
          return state;
        default:
          return state;
      }

    case 'opening':
      switch (event.type) {
        case 'OPEN':
          // Already opening, stay opening (idempotent)
          return state;
        case 'CLOSE':
        case 'TOGGLE':
          // User requested close during opening, go to closing
          return {
            visibility: 'closing',
            shouldRender: true,
            shouldShow: false,
            keyboardNavActive: false,
            clickOutsideActive: false,
          };
        case 'ANIMATION_END':
          // Opening animation finished, now fully open
          return {
            visibility: 'open',
            shouldRender: true,
            shouldShow: true,
            keyboardNavActive: true,
            clickOutsideActive: true,
          };
        default:
          return state;
      }

    case 'open':
      switch (event.type) {
        case 'OPEN':
        case 'ANIMATION_END':
          // Already open, stay open (idempotent)
          return state;
        case 'CLOSE':
        case 'TOGGLE':
          // User requested close
          return {
            visibility: 'closing',
            shouldRender: true,
            shouldShow: false,
            keyboardNavActive: false,
            clickOutsideActive: false,
          };
        default:
          return state;
      }

    case 'closing':
      switch (event.type) {
        case 'OPEN':
        case 'TOGGLE':
          // User requested open during closing, go back to opening
          return {
            visibility: 'opening',
            shouldRender: true,
            shouldShow: false,
            keyboardNavActive: false,
            clickOutsideActive: false,
          };
        case 'CLOSE':
          // Already closing, stay closing (idempotent)
          return state;
        case 'ANIMATION_END':
          // Closing animation finished, now fully closed
          return {
            visibility: 'closed',
            shouldRender: false,
            shouldShow: false,
            keyboardNavActive: false,
            clickOutsideActive: false,
          };
        default:
          return state;
      }

    default:
      return state;
  }
}

/**
 * Compute the data-visual-state attribute value from FSM state
 *
 * @param state - Current FSM state
 * @returns String for data-visual-state attribute
 */
export function getDropdownVisualState(state: DropdownFSMState): string {
  return state.visibility;
}

import {
  autoUpdate,
  flip,
  FloatingFocusManager,
  FloatingList,
  offset,
  shift,
  useClick,
  useDismiss,
  useFloating,
  useInteractions,
  useListItem,
  useListNavigation,
  useMergeRefs,
  useRole,
  useTypeahead,
} from '@floating-ui/react';
import {
  createContext,
  forwardRef,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useReducer,
  useRef,
  useState,
} from 'react';
import { createPortal } from 'react-dom';

import { cn } from '../../utils';
import { mapPlacement } from '../../utils/misc';
import { isValidHref } from '../../utils/validation';

import {
  createInitialDropdownFSMState,
  dropdownFSMReducer,
  getDropdownVisualState,
} from './Dropdown.fsm';

import type {
  DropdownAutoClose,
  DropdownContextValue,
  DropdownDividerProps,
  DropdownHeaderProps,
  DropdownItemProps,
  DropdownItemTextProps,
  DropdownMenuProps,
  DropdownPlacement,
  DropdownProps,
  DropdownToggleProps,
} from './Dropdown.types';
import type { FloatingContext } from '@floating-ui/react';
import type { ReactNode } from 'react';

/**
 * Dropdown context for sharing state between components
 */
const DropdownContext = createContext<DropdownContextValue | null>(null);

/**
 * Hook to access dropdown context
 */
function useDropdownContext(): DropdownContextValue {
  const context = useContext(DropdownContext);
  if (!context) {
    throw new Error('Dropdown components must be used within a Dropdown component');
  }
  return context;
}

function extractTextContent(node: ReactNode): string {
  if (typeof node === 'string' || typeof node === 'number') {
    return String(node).trim();
  }

  if (Array.isArray(node)) {
    return node
      .map((child) => extractTextContent(child))
      .filter(Boolean)
      .join(' ')
      .trim();
  }

  if (isValidElement(node)) {
    const elementProps = node.props as Record<string, unknown> & {
      children?: ReactNode;
      title?: string;
      'aria-label'?: string;
    };
    const ariaLabel =
      typeof elementProps['aria-label'] === 'string' ? elementProps['aria-label'].trim() : '';
    const title = typeof elementProps.title === 'string' ? elementProps.title.trim() : '';

    if (ariaLabel) {
      return ariaLabel;
    }

    if (title) {
      return title;
    }

    return extractTextContent(elementProps.children);
  }

  return '';
}

/**
 * Map DSAi placement to Floating UI placement
 */

/**
 * Dropdown Component
 *
 * A fully accessible dropdown menu component with FSM-driven state management,
 * Floating UI positioning, and keyboard navigation.
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - aria-haspopup on trigger
 * - aria-expanded state management
 * - Arrow key navigation within menu
 * - Type-ahead search
 * - ESC to close
 * - Focus trap while open
 *
 * SECURITY FEATURES:
 * - Prop whitelisting
 * - Safe href validation
 * - No unrestricted prop spreading
 *
 * @example
 * ```tsx
 * <Dropdown>
 *   <Dropdown.Toggle>Options</Dropdown.Toggle>
 *   <Dropdown.Menu>
 *     <Dropdown.Item onClick={handleAction}>Action</Dropdown.Item>
 *     <Dropdown.Divider />
 *     <Dropdown.Item href="/settings">Settings</Dropdown.Item>
 *   </Dropdown.Menu>
 * </Dropdown>
 * ```
 */
const DropdownRoot = forwardRef<HTMLDivElement, DropdownProps>(
  (
    {
      children,
      isOpen: controlledIsOpen,
      onOpenChange,
      defaultOpen = false,
      placement = 'bottom-start',
      autoClose = true,
      offset: offsetValue = [0, 2],
      disabled = false,
      onOpened,
      onClosed,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    // Determine if controlled
    const isControlled = controlledIsOpen !== undefined;

    // Generate IDs for accessibility
    const generatedId = useId();
    const toggleId = `dropdown-toggle-${id ?? generatedId}`;
    const menuId = `dropdown-menu-${id ?? generatedId}`;

    // FSM for state management
    const [fsmState, dispatch] = useReducer(
      dropdownFSMReducer,
      isControlled ? controlledIsOpen : defaultOpen,
      createInitialDropdownFSMState
    );

    // For animated transitions
    const [animatedShowClass, setAnimatedShowClass] = useState(
      () => (isControlled ? controlledIsOpen : defaultOpen) === true
    );

    // List navigation state
    const [activeIndex, setActiveIndex] = useState<number | null>(null);
    const listRef = useRef<(HTMLElement | null)[]>([]);
    const listContentRef = useRef<(string | null)[]>([]);

    // Compute isOpen from FSM
    const isOpen = fsmState.visibility === 'open' || fsmState.visibility === 'opening';

    // Floating UI setup
    const { refs, floatingStyles, context } = useFloating({
      open: fsmState.shouldRender,
      onOpenChange: (open) => {
        if (disabled) {
          return;
        }
        if (open) {
          dispatch({ type: 'OPEN' });
          // Always call onOpenChange callback if provided
          onOpenChange?.(true);
        } else {
          dispatch({ type: 'CLOSE' });
          // Always call onOpenChange callback if provided
          onOpenChange?.(false);
        }
      },
      placement: mapPlacement(placement),
      middleware: [
        offset({ mainAxis: offsetValue[1], crossAxis: offsetValue[0] }),
        flip({ fallbackAxisSideDirection: 'end' }),
        shift({ padding: 5 }),
      ],
      whileElementsMounted: autoUpdate,
    });

    // Interaction hooks
    const click = useClick(context, {
      enabled: !disabled && !isControlled,
      toggle: true,
    });

    const dismiss = useDismiss(context, {
      enabled: autoClose !== false,
      // Disable outsidePress in controlled mode to prevent race condition
      // with external toggle buttons. ESC key still works and calls onOpenChange.
      outsidePress: !isControlled && (autoClose === true || autoClose === 'outside'),
      escapeKey: true,
    });

    const role = useRole(context, { role: 'menu' });

    const listNavigation = useListNavigation(context, {
      listRef,
      activeIndex,
      onNavigate: setActiveIndex,
      loop: true,
    });

    const typeahead = useTypeahead(context, {
      listRef: listContentRef,
      activeIndex,
      onMatch: setActiveIndex,
    });

    const { getReferenceProps, getFloatingProps, getItemProps } = useInteractions([
      click,
      dismiss,
      role,
      listNavigation,
      typeahead,
    ]);

    // Sync controlled state with FSM
    useEffect(() => {
      if (!isControlled) {
        return;
      }

      if (controlledIsOpen && fsmState.visibility === 'closed') {
        dispatch({ type: 'OPEN' });
      } else if (
        !controlledIsOpen &&
        (fsmState.visibility === 'open' || fsmState.visibility === 'opening')
      ) {
        dispatch({ type: 'CLOSE' });
      }
    }, [isControlled, controlledIsOpen, fsmState.visibility]);

    // Handle animation transitions - dropdowns have minimal/no animations
    // so we dispatch ANIMATION_END immediately to complete the state transition
    useEffect(() => {
      if (fsmState.visibility === 'opening') {
        // Use rAF to allow the DOM to render first, then complete the transition
        const frameId = requestAnimationFrame(() => {
          dispatch({ type: 'ANIMATION_END' });
        });
        return () => cancelAnimationFrame(frameId);
      }

      if (fsmState.visibility === 'closing') {
        // Use rAF to allow closing animations if any
        const frameId = requestAnimationFrame(() => {
          dispatch({ type: 'ANIMATION_END' });
        });
        return () => cancelAnimationFrame(frameId);
      }

      return undefined;
    }, [fsmState.visibility]);

    // Handle animation class for CSS transitions
    useEffect(() => {
      if (fsmState.visibility === 'opening' && !animatedShowClass) {
        // Use rAF for smooth animation trigger
        let innerFrameId: number | undefined;
        const frameId = requestAnimationFrame(() => {
          innerFrameId = requestAnimationFrame(() => {
            setAnimatedShowClass(true);
          });
        });
        return () => {
          cancelAnimationFrame(frameId);
          if (innerFrameId !== undefined) {
            cancelAnimationFrame(innerFrameId);
          }
        };
      }

      if (fsmState.visibility === 'closed' && animatedShowClass) {
        const timeoutId = setTimeout(() => {
          setAnimatedShowClass(false);
        }, 0);
        return () => clearTimeout(timeoutId);
      }

      return undefined;
    }, [fsmState.visibility, animatedShowClass]);

    // Handle callbacks
    useEffect(() => {
      if (fsmState.visibility === 'open' && onOpened) {
        onOpened();
      }
    }, [fsmState.visibility, onOpened]);

    useEffect(() => {
      if (fsmState.visibility === 'closed' && onClosed) {
        onClosed();
      }
    }, [fsmState.visibility, onClosed]);

    // Context actions - let React Compiler handle memoization
    const toggle = (): void => {
      if (disabled) {
        return;
      }
      dispatch({ type: 'TOGGLE' });
      if (isControlled && onOpenChange) {
        onOpenChange(!isOpen);
      }
    };

    const open = (): void => {
      if (disabled) {
        return;
      }
      dispatch({ type: 'OPEN' });
      if (isControlled && onOpenChange) {
        onOpenChange(true);
      }
    };

    const close = (): void => {
      dispatch({ type: 'CLOSE' });
      if (isControlled && onOpenChange) {
        onOpenChange(false);
      }
    };

    // Context value - React Compiler handles memoization
    const contextValue: DropdownContextValue = {
      isOpen,
      toggle,
      open,
      close,
      disabled,
      placement,
      autoClose,
      toggleId,
      menuId,
      activeIndex,
      setActiveIndex,
      listRef,
      getItemProps,
      refs: {
        setReference: refs.setReference,
        setFloating: refs.setFloating,
      },
      floatingStyles,
      getReferenceProps,
      getFloatingProps,
      floatingContext: context,
    };

    // Compute direction class for Bootstrap
    const directionClass = useMemo(() => {
      if (placement.startsWith('top')) {
        return 'dropup';
      }
      if (placement.startsWith('left')) {
        return 'dropstart';
      }
      if (placement.startsWith('right')) {
        return 'dropend';
      }
      if (placement === 'bottom' || placement === 'bottom-end') {
        return 'dropdown';
      }
      return 'dropdown';
    }, [placement]);

    const containerClassName = useMemo(
      () => cn('btn-group', directionClass, className),
      [directionClass, className]
    );

    return (
      <DropdownContext.Provider value={contextValue}>
        <FloatingList elementsRef={listRef} labelsRef={listContentRef}>
          <div
            ref={ref}
            className={containerClassName}
            style={style}
            id={id}
            data-testid={dataTestId}
            data-test={dataTest}
            data-visual-state={getDropdownVisualState(fsmState)}
          >
            {children}
          </div>
        </FloatingList>
      </DropdownContext.Provider>
    );
  }
);

DropdownRoot.displayName = 'Dropdown';

/**
 * Dropdown.Toggle Component
 *
 * The trigger button that opens/closes the dropdown menu.
 */
const DropdownToggle = forwardRef<HTMLButtonElement, DropdownToggleProps>(
  (
    {
      children,
      variant = 'secondary',
      size = 'md',
      split = false,
      caret = true,
      disabled: toggleDisabled = false,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
      'aria-label': ariaLabel,
    },
    ref
  ) => {
    const {
      isOpen,
      disabled: contextDisabled,
      toggleId,
      menuId,
      refs,
      getReferenceProps,
    } = useDropdownContext();

    const isDisabled = toggleDisabled || contextDisabled;
    const derivedLabel = useMemo(() => extractTextContent(children), [children]);
    const computedAriaLabel = useMemo(() => {
      const normalizedAriaLabel = ariaLabel?.trim();
      if (normalizedAriaLabel) {
        return normalizedAriaLabel;
      }
      if (derivedLabel) {
        return derivedLabel;
      }
      return 'Toggle Dropdown';
    }, [ariaLabel, derivedLabel]);

    // Development warning for split toggles without explicit aria-label (guarded for browser envs)
    if (
      typeof process !== 'undefined' &&
      process.env?.['NODE_ENV'] !== 'production' &&
      split &&
      !ariaLabel
    ) {
      console.warn(
        'Dropdown.Toggle: Split toggles should have an explicit aria-label for accessibility. ' +
          'Falling back to "Toggle Dropdown".'
      );
    }

    // Compute Bootstrap button classes
    const buttonClassName = useMemo(
      () =>
        cn(
          'btn',
          `btn-${variant}`,
          size === 'sm' && 'btn-sm',
          size === 'lg' && 'btn-lg',
          caret && 'dropdown-toggle',
          split && 'dropdown-toggle-split',
          className
        ),
      [variant, size, caret, split, className]
    );

    const mergedRef = useMergeRefs([ref, refs.setReference]);

    return (
      <button
        ref={mergedRef}
        type="button"
        {...getReferenceProps()}
        id={id ?? toggleId}
        className={buttonClassName}
        style={style}
        disabled={isDisabled}
        aria-haspopup="menu"
        aria-expanded={isOpen}
        aria-controls={isOpen ? menuId : undefined}
        aria-label={computedAriaLabel}
        data-testid={dataTestId}
        data-test={dataTest}
      >
        {split ? <span className="visually-hidden">{computedAriaLabel}</span> : children}
      </button>
    );
  }
);

DropdownToggle.displayName = 'Dropdown.Toggle';

/**
 * Dropdown.Menu Component
 *
 * The container for dropdown items, rendered in a portal.
 */
const DropdownMenu = forwardRef<HTMLUListElement, DropdownMenuProps>(
  (
    {
      children,
      align = 'start',
      portal = true,
      container = typeof document !== 'undefined' ? document.body : null,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    const { isOpen, menuId, toggleId, refs, floatingStyles, getFloatingProps, floatingContext } =
      useDropdownContext();

    // Compute menu classes
    const menuClassName = useMemo(
      () =>
        cn('dropdown-menu', isOpen && 'show', align === 'end' && 'dropdown-menu-end', className),
      [isOpen, align, className]
    );

    const mergedRef = useMergeRefs([ref, refs.setFloating]);

    // Combine floating styles with user styles
    const combinedStyle = useMemo(
      () => ({
        ...floatingStyles,
        ...style,
      }),
      [floatingStyles, style]
    );

    if (!isOpen) {
      return null;
    }

    const menuContent = (
      <FloatingFocusManager
        context={floatingContext as FloatingContext}
        modal={false}
        // @ts-expect-error floating-ui typings may not include inert yet
        inert={false}
      >
        <ul
          ref={mergedRef}
          id={id ?? menuId}
          className={menuClassName}
          style={combinedStyle}
          aria-labelledby={toggleId}
          data-testid={dataTestId}
          data-test={dataTest}
          {...getFloatingProps()}
        >
          {children}
        </ul>
      </FloatingFocusManager>
    );

    if (portal && container) {
      return createPortal(menuContent, container);
    }

    return menuContent;
  }
);

DropdownMenu.displayName = 'Dropdown.Menu';

/**
 * Dropdown.Item Component
 *
 * A clickable item within the dropdown menu.
 */
const DropdownItem = forwardRef<HTMLButtonElement | HTMLAnchorElement, DropdownItemProps>(
  (
    {
      children,
      onClick,
      onKeyDown,
      href,
      target,
      rel,
      active = false,
      disabled = false,
      startIcon,
      endIcon,
      as,
      className = '',
      style,
      id,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    const { close, autoClose, getItemProps, activeIndex } = useDropdownContext();
    const { ref: itemRef, index } = useListItem();

    // Validate href for security
    const safeHref = isValidHref(href) ? href : undefined;

    // Determine element type
    const ElementType = as ?? (safeHref ? 'a' : 'button');

    // Compute item classes
    const itemClassName = useMemo(
      () => cn('dropdown-item', active && 'active', disabled && 'disabled', className),
      [active, disabled, className]
    );

    // Handle click
    const handleClick = useCallback(
      (event: React.MouseEvent<HTMLButtonElement | HTMLAnchorElement>) => {
        if (disabled) {
          event.preventDefault();
          return;
        }

        onClick?.(event);

        // Auto-close logic
        if (autoClose === true || autoClose === 'inside') {
          close();
        }
      },
      [disabled, onClick, autoClose, close]
    );

    // Compute rel for links
    const computedRel = useMemo(() => {
      if (!safeHref) {
        return undefined;
      }
      if (rel) {
        return rel;
      }
      if (target === '_blank') {
        return 'noopener noreferrer';
      }
      return undefined;
    }, [safeHref, rel, target]);

    const mergedRef = useMergeRefs([ref, itemRef]);

    const itemProps = getItemProps({
      onClick: handleClick,
      onKeyDown,
    });

    const isActive = index === activeIndex;

    if (ElementType === 'a') {
      return (
        <li role="none">
          <a
            ref={mergedRef as React.Ref<HTMLAnchorElement>}
            id={id}
            className={itemClassName}
            style={style}
            href={safeHref}
            target={target}
            rel={computedRel}
            role="menuitem"
            aria-disabled={disabled}
            aria-current={active ? 'true' : undefined}
            tabIndex={isActive ? 0 : -1}
            data-testid={dataTestId}
            data-test={dataTest}
            {...itemProps}
          >
            {startIcon && (
              <span className="dropdown-item-icon me-2" aria-hidden="true">
                {startIcon}
              </span>
            )}
            {children}
            {endIcon && (
              <span className="dropdown-item-icon ms-2" aria-hidden="true">
                {endIcon}
              </span>
            )}
          </a>
        </li>
      );
    }

