/**
 * Dropdown.Menu component props
 *
 * The container for dropdown items. Rendered in a portal for proper positioning.
 *
 * @example
 * ```tsx
 * // Basic menu
 * <Dropdown.Menu>
 *   <Dropdown.Item>Item 1</Dropdown.Item>
 *   <Dropdown.Item>Item 2</Dropdown.Item>
