  children: ReactNode;

  /**
   * Menu alignment (overrides parent placement for simple cases)
   * @default 'start'
   */
  align?: 'start' | 'end';

  /**
   * Whether to render the menu in a portal
   * @default true
   */
  portal?: boolean;

  /**
   * Container element for the portal
   * @default document.body
