/**
 * Dropdown.Item component props
 *
 * A clickable item within the dropdown menu.
 * Can be rendered as a button or anchor based on props.
 *
 * @example
 * ```tsx
 * // Button item (action)
 * <Dropdown.Item onClick={handleAction}>
 *   Perform Action
 * </Dropdown.Item>
